"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["28066"],{49535(e){e.exports=JSON.parse('{"id":"F313","slug":"cdo-equity-return","name":"CDO Equity Tranche Return","subject":"Fixed Income","section":"Securitized Products","topic":"Collateralized debt obligations (CDOs)","level":"Intermediate","aliases":["collateralized debt obligation","arbitrage CDO","equity tranche","leverage in structured credit"],"formula":{"latex":"R_{equity}=\\\\frac{A\\\\,y-\\\\sum L_{i}\\\\,k_{i}-f\\\\,A-\\\\text{Losses}}{E}","also":[],"text":"Equity return = (Interest earned on the assets - Interest paid on each debt tranche - Fees - Credit losses) / Equity invested"},"symbols":[{"symbol":"A","meaning":"Total assets in the pool","unit":"money"},{"symbol":"y","meaning":"Average yield on the pool","unit":"per year"},{"symbol":"L_i, k_i","meaning":"Size and interest rate of each debt tranche","unit":"money"},{"symbol":"f","meaning":"Annual fees as a share of assets","unit":"per year"},{"symbol":"E","meaning":"Equity tranche invested, the first-loss piece","unit":"money"}],"when_to_use":"Use it to see how a CDO magnifies returns for its equity holders. The equity tranche borrows cheaply from the debt tranches, so it keeps the spread between the asset yield and the liability costs, and also takes the first losses. That makes it high-return and high-risk.","worked_example":{"problem":"A CDO holds assets of 100 yielding 7.0%. It issues 75 of senior notes at 4.5% and 15 of mezzanine notes at 6.0%, leaving 10 of equity. Fees are 0.4% of assets. What is the equity return with no losses, and with 1% of assets lost?","inputs":{"a":100,"y":7,"ls":75,"ks":4.5,"lm":15,"km":6,"f":0.4,"loss":1},"steps":[{"label":"Equity = assets - senior - mezzanine","working":"100-75-15","value":"10.00"},{"label":"Income = assets x yield","working":"100 x 0.07","value":"7.000"},{"label":"Interest on notes = senior x rate + mezzanine x rate","working":"75 x 0.045+15 x 0.06","value":"4.275"},{"label":"Income after interest and fees","working":"7-4.275-0.004 x 100","value":"2.325"},{"label":"Equity return with no losses","working":"2.325 / 10","value":"23.25%"},{"label":"Credit losses = assets x loss rate","working":"100 x 0.01","value":"1.00"},{"label":"Equity return after losses","working":"(2.325-1) / 10","value":"13.25%"}],"answer":"Income after costs is 2.325, a return of 23.25% on the equity of 10.00. With credit losses of 1.00 the equity return falls to 13.25%. A loss of just 1% of the assets cuts the equity return by about a third."},"calculator":{"available":true,"inputs":[{"id":"a","label":"Asset pool","unit":"money","type":"number","default":100,"hint":""},{"id":"y","label":"Asset yield","unit":"%","type":"number","default":7,"hint":""},{"id":"ls","label":"Senior notes","unit":"money","type":"number","default":75,"hint":""},{"id":"ks","label":"Senior note rate","unit":"%","type":"number","default":4.5,"hint":""},{"id":"lm","label":"Mezzanine notes","unit":"money","type":"number","default":15,"hint":""},{"id":"km","label":"Mezzanine note rate","unit":"%","type":"number","default":6,"hint":""},{"id":"f","label":"Annual fees (share of assets)","unit":"%","type":"number","default":0.4,"hint":""},{"id":"loss","label":"Credit losses (share of assets)","unit":"%","type":"number","default":1,"hint":""}],"checks":[{"expr":"a>ls+lm","message":"The assets must be larger than the debt, so some equity remains."}],"steps":[{"id":"eq","label":"Equity = assets - senior - mezzanine","expr":"a-ls-lm","format":"num2"},{"id":"inc","label":"Income = assets x yield","expr":"a*y","format":"num3"},{"id":"cost","label":"Interest on notes = senior x rate + mezzanine x rate","expr":"ls*ks+lm*km","format":"num3"},{"id":"net","label":"Income after interest and fees","expr":"inc-cost-f*a","format":"num3"},{"id":"r0","label":"Equity return with no losses","expr":"net/eq","format":"pct2"},{"id":"lossamt","label":"Credit losses = assets x loss rate","expr":"a*loss","format":"num2"},{"id":"r1","label":"Equity return after losses","expr":"(net-lossamt)/eq","format":"pct2"}],"results":["r0","r1"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"eq":10,"net":2.325,"r0":0.2325,"r1":0.1325}},"finder":{"finds":"The equity return of a collateralized debt obligation","needs":"Asset pool and yield, debt tranches, fees, losses"},"related":[{"slug":"tranche-loss","name":"Tranche Loss Allocation (Attachment and Detachment)"},{"slug":"clo-oc-test","name":"CLO Overcollateralization Test"},{"slug":"mm-levered-value","name":"Value of a Levered Firm (Modigliani-Miller with Taxes)"}],"related_ids":["F316","F314","F169"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>R</mi><mrow><mi>e</mi><mi>q</mi><mi>u</mi><mi>i</mi><mi>t</mi><mi>y</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>A</mi><mtext>\u2009</mtext><mi>y</mi><mo>\u2212</mo><mo>\u2211</mo><msub><mi>L</mi><mi>i</mi></msub><mtext>\u2009</mtext><msub><mi>k</mi><mi>i</mi></msub><mo>\u2212</mo><mi>f</mi><mtext>\u2009</mtext><mi>A</mi><mo>\u2212</mo><mtext>Losses</mtext></mrow><mi>E</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">R_{equity}=\\\\frac{A\\\\,y-\\\\sum L_{i}\\\\,k_{i}-f\\\\,A-\\\\text{Losses}}{E}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"cat-bond-expected-loss","name":"Catastrophe Bond: Expected Loss and Risk Multiple"},"next":{"slug":"ccp-initial-margin","name":"Central Counterparty Initial Margin (Value-at-Risk Method)"},"lesson":null,"total":522}')}}]);